
fn seeded(n:u64)->sha3::Shake256Reader{let mut h=Shake256::default();h.update(b"fixed-input-rng-anf-validation-v1");h.update(&n.to_le_bytes());h.finalize_xof()}
fn main(){let args:Vec<_>=std::env::args().collect();let ops=load_ops(&args[1]).unwrap();let(nq,nb,_,regs)=analyze_ops(ops.iter());let rows:Vec<Vec<U256>>=std::fs::read_to_string(&args[2]).unwrap().lines().filter(|x|!x.trim().is_empty()).take(64).map(|x|x.split_whitespace().skip(1).map(|v|U256::from_str_radix(v.trim_start_matches("0x"),16).unwrap()).collect()).collect();assert!(!rows.is_empty()&&rows.iter().all(|x|x.len()==6));let cap=args.get(3).map(|x|x.parse().unwrap()).unwrap_or(32);let mut alg=FixedAnf::new(cap,0);let mut dummy=seeded(0);let mut initial=Simulator::new(nq as usize,nb as usize,&mut dummy);let mut expected=[vec![0u64;regs[0].len()],vec![0u64;regs[1].len()]];for(lane,row)in rows.iter().enumerate(){for(reg,v)in regs[..4].iter().zip(&row[..4]){initial.set_register(reg,*v,lane);}for reg in 0..2{for i in 0..expected[reg].len(){expected[reg][i]|=(row[4+reg].bit(i)as u64)<<lane;}}}let initialq=initial.qubits.clone();let initialb=initial.bits.clone();drop(initial);let mut q:Vec<_>=initialq.iter().map(|x|Poly::constant(*x)).collect();let mut b:Vec<_>=initialb.iter().map(|x|Poly::constant(*x)).collect();let mut base=Poly::constant(u64::MAX);let mut stack=Vec::new();let start=std::time::Instant::now();let mut mr=0usize;
 for(i,o)in ops.iter().enumerate(){use OperationType::*;if matches!(o.kind,Neg|Z|CZ|CCZ|Register|AppendToRegister|DebugPrint){continue;}if o.kind==PopCondition{base=stack.pop().unwrap();continue;}let c=if o.c_condition.0==u64::MAX{base.clone()}else{alg.and(&base,&b[o.c_condition.0 as usize])};let t=o.q_target.0 as usize;let bt=o.c_target.0 as usize;match o.kind{CCX=>{let v=alg.and(&q[o.q_control1.0 as usize],&q[o.q_control2.0 as usize]);let v=alg.and(&v,&c);q[t]=alg.xor(&q[t],&v);},CX=>{let v=alg.and(&q[o.q_control1.0 as usize],&c);q[t]=alg.xor(&q[t],&v);},X=>q[t]=alg.xor(&q[t],&c),Swap=>{let a=o.q_control1.0 as usize;let v=alg.xor(&q[t],&q[a]);let v=alg.and(&v,&c);q[t]=alg.xor(&q[t],&v);q[a]=alg.xor(&q[a],&v);},R|Hmr=>{mr+=1;let nc=alg.not(&c);q[t]=alg.and(&q[t],&nc);if o.kind==Hmr{let random=alg.fresh(u64::MAX);let old=alg.and(&b[bt],&nc);let new=alg.and(&random,&c);b[bt]=alg.xor(&old,&new);}},BitStore0=>{let nc=alg.not(&c);b[bt]=alg.and(&b[bt],&nc);},BitStore1=>{let nc=alg.not(&c);let old=alg.and(&b[bt],&nc);b[bt]=alg.xor(&old,&c);},BitInvert=>b[bt]=alg.xor(&b[bt],&c),PushCondition=>{stack.push(base);base=c;},_=>unreachable!()}
 if i%500000==0{eprintln!("FIXED_ANF_PROGRESS ops={i} caps={} fresh_symbols={} seconds={:.1}",alg.capped,alg.next,start.elapsed().as_secs_f64());}}
 assert!(stack.is_empty());let mask=if rows.len()==64{u64::MAX}else{(1u64<<rows.len())-1};let mut wrong=0u64;let(mut knownbits,mut allbits)=(0usize,0usize);for(reg,expected)in regs[..2].iter().zip(expected.iter()){for(wire,e)in reg.iter().zip(expected){let poly=match wire{QubitOrBit::Qubit(id)=>&q[id.0 as usize],QubitOrBit::Bit(id)=>&b[id.0 as usize]};let(c,k)=poly.known();knownbits+=(k&mask).count_ones()as usize;allbits+=rows.len();wrong|=(c^e)&k&mask;}}let seconds=start.elapsed().as_secs_f64();let intern_hits=alg.intern_hits;let intern_clears=alg.intern_clears;let intern_nodes=alg.intern.len();
 for seed in 0..4{let mut random=seeded(seed);let mut s=Simulator::new(nq as usize,nb as usize,&mut random);s.qubits.copy_from_slice(&initialq);s.bits.copy_from_slice(&initialb);s.apply_iter(ops.iter());for(i,p)in q.iter().enumerate(){let(c,k)=p.known();assert_eq!((s.qubits[i]^c)&k,0,"quantum containment wire{i} seed{seed}");}for(i,p)in b.iter().enumerate(){let(c,k)=p.known();assert_eq!((s.bits[i]^c)&k,0,"classical containment wire{i} seed{seed}");}for lane in 0..rows.len(){if wrong>>lane&1!=0{assert!(s.get_register(&regs[0],lane)!=rows[lane][4]||s.get_register(&regs[1],lane)!=rows[lane][5]);}}}
 println!("{{\"shots\":{},\"term_cap\":{cap},\"intern_hits\":{intern_hits},\"intern_clears\":{intern_clears},\"intern_nodes\":{intern_nodes},\"capped_expressions\":{},\"fresh_symbols\":{},\"rng_draws\":{mr},\"output_known_bits\":{knownbits},\"output_all_bits\":{allbits},\"certified_wrong_lanes_hex\":\"{wrong:016x}\",\"certified_wrong_shots\":{},\"protected_containment_seeds\":4,\"seconds\":{seconds:.6},\"status\":\"RESEARCH_CERTIFICATE_NOT_ENABLED_FOR_SCREENING\"}}",rows.len(),alg.capped,alg.next,wrong.count_ones());}
